head.script:
        function add() {
            arr.push("banana", "watermelon", "avocado");
        }

        function remove() {
            arr.pop();
            arr.pop();
        }

        arr = ["apple", "orange", "mango"];
        document.write("Original Array : [" + arr + "]" + "

");

        add();
        document.write("Array after push : [" + arr + "]" + "

");

        remove();
        document.write("Array after pop : [" + arr + "]" + "

");

        document.write("String : " + arr.toString());
